function validate([nums, n, left, right]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (n !== nums.length) return 'n must equal the length of nums.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of nums is an integer from 1 to 100.';
  const count = (n * (n + 1)) / 2;
  if (!Number.isInteger(left) || !Number.isInteger(right) || left < 1 || left > right || right > count) return 'Need 1 <= left <= right <= n * (n + 1) / 2.';
  return null;
}

