function rangeSum(nums, n, left, right) {
  const MOD = 1_000_000_007;
  const sums = [];

  for (let start = 0; start < n; start++) {
    let total = 0;
    for (let end = start; end < n; end++) {
      total += nums[end];
      sums.push(total);
    }
  }
  sums.sort((a, b) => a - b);

  let answer = 0;
  for (let k = left - 1; k < right; k++) {
    answer = (answer + sums[k]) % MOD;
  }
  return answer;
}

