function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(700, 1000) : pick(1, 7);
  const top = size === 'large' ? 100 : pick(1, 12);
  const flat = rand() < 0.2;
  const nums = Array.from({ length: n }, () => (flat ? top : pick(1, top)));
  const count = (n * (n + 1)) / 2;
  let left;
  let right;
  if (rand() < 0.25) {
    left = 1;
    right = count;
  } else {
    left = pick(1, count);
    right = pick(left, count);
  }
  return [nums, n, left, right];
}
